from term import Atom
from pyrlang.gen.server import GenServer  # pylint: disable=no-name-in-module
from pyrlang.gen.decorators import cast  # pylint: disable=no-name-in-module

PYTHON_REGISTERED_NAME = 'uex_log_handler'


class UexLogHandler(GenServer):
    def __init__(self, logger):
        super(UexLogHandler, self).__init__()
        self.logger = logger
        self.get_node().register_name(self, Atom(PYTHON_REGISTERED_NAME))

    @cast(1, lambda msg: True)
    def handle_cast(self, msg):
        """Handle cast"""
        level = msg[0]  # TODO check for robot loglevel
        message = msg[1].decode('utf-8')
        try:
            getattr(self.logger, level)(message)
        except AttributeError:
            pass
